@if(config('analytics.enabled'))
<div id="analytics-consent" hidden role="dialog" aria-live="polite" style="position:fixed;z-index:9999;left:1rem;right:1rem;bottom:1rem;max-width:680px;margin:auto;padding:1rem;background:#fff;color:#172033;border:1px solid #ccd3df;box-shadow:0 8px 30px #0003"><strong>Privacy choices</strong><p style="margin:.5rem 0">Allow anonymous analytics to help us improve this website. Essential cookies always remain enabled.</p><button type="button" data-analytics-choice="accepted">Allow analytics</button> <button type="button" data-analytics-choice="declined">Decline</button></div>
<script>(()=>{const key='barqaab_analytics_consent',banner=document.getElementById('analytics-consent'),load=()=>{if(document.querySelector('[data-site-analytics]'))return;@if(config('analytics.provider') === 'google' && config('analytics.google_measurement_id'))const id=@js(config('analytics.google_measurement_id')),script=document.createElement('script');script.async=true;script.dataset.siteAnalytics='google';script.src=`https://www.googletagmanager.com/gtag/js?id=${encodeURIComponent(id)}`;document.head.appendChild(script);window.dataLayer=window.dataLayer||[];window.gtag=function(){dataLayer.push(arguments)};gtag('js',new Date());gtag('config',id,{anonymize_ip:true});@elseif(config('analytics.provider') === 'plausible' && config('analytics.plausible_domain'))const script=document.createElement('script');script.defer=true;script.dataset.siteAnalytics='plausible';script.dataset.domain=@js(config('analytics.plausible_domain'));script.src=@js(config('analytics.plausible_script'));document.head.appendChild(script);@endif},choice=localStorage.getItem(key);if(choice==='accepted')load();if(!choice)banner.hidden=false;banner.querySelectorAll('[data-analytics-choice]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.analyticsChoice;localStorage.setItem(key,value);banner.hidden=true;if(value==='accepted')load()}))})();</script>
